import type { ChordQualityId, ConceptId, FragTag, Fragment, Tier } from '../../types';
import { parseNotes } from './notation';

/**
 * Focus cells (original, authored by pattern in 16th-note units like vocab.ts, scaled x3 on load). Each cell is written for one
 * Focus concept and is offered only while that Focus is on (Fragment.concept), so generation without a Focus is unchanged:
 *  - enclosures / chromatic approaches: upper + lower neighbour (or a chromatic note) into a chord tone on a beat or the "and",
 *    in quarters and eighths at Beginner, 16ths and three-note approaches at Expert;
 *  - guide tones (L3-L4): first and last notes are the 3rd / 7th (6th), a stepwise line between;
 *  - triad pairs: two triads a whole step apart (maj7 I/II, m7 bIII/IV and Dm/Em, dom7 I/bVII, I/II and Gm/Am, 7alt bVI/bV and bIIm/bIIIm);
 *  - Barry Harris 6th-diminished lines over maj7 and m6;
 *  - superimposition: a ii7-V7 arpeggio, a tritone-substitute arpeggio, or a chord-tone figure side-slipped a half step that resolves.
 * Every cell obeys the fragment rules (tests/fragments.test.ts) and is found by the matching detector in src/theory/devices.ts
 * (tests/devices.test.ts).
 */
type Q = ChordQualityId;
const f = (id: string, qualities: Q[], beats: 2 | 4, level: Tier, concept: ConceptId, tags: FragTag[], notes: string): Fragment =>
  ({ id, qualities, beats, notes: parseNotes(notes, 1), tags, level, concept, source: 'original' });
const e = (id: string, qualities: Q[], beats: 2 | 4, level: Tier, concept: ConceptId, tags: FragTag[], notes: string): Fragment => ({ ...f(id, qualities, beats, level, concept, tags, notes), ending: true });
